INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q15197330', 'Battle of Manila', 'The Battle of Manila (1574) (Spanish: Batalla de Manila de 1574; Filipino: Labanan sa Maynila ng 1574) was fought on 29 November 1574 between Chinese and Japanese pirates led by Limahong and Spanish colonial forces with their native allies. It took place near Manila, mainly in what is now Parañaque, in the Philippines.', 1574, 11, 29, NULL, NULL, NULL, 'day', '29 November 1574', 37, 'https://en.wikipedia.org/wiki/Battle_of_Manila_(1574)'),
  ('Q8348305', '1582 Cagayan battles', 'The Cagayan battles (Combates de Cagayán in Spanish, カガヤンの戦い Kagayan no Tatakai in Japanese) occurred in 1582 between amphibious forces of the Spanish Philippines, led by Juan Pablo de Carrión, and Japanese wokou pirates, led by Tay Fusa, possibly identified with Naya Sukezaemon. The pirates had build a settlement near the Cagayan river, which the Spanish were ordered to assault.', 1582, NULL, NULL, NULL, NULL, NULL, 'year', '1582', 41, 'https://en.wikipedia.org/wiki/1582_Cagayan_battles'),
  ('Q1933282', 'Battle of Playa Honda', 'The naval Second Battle of Playa Honda (Spanish: Segunda La Batalla Naval de Playa Honda; Filipino: Ikalawang Labanan sa Playa Honda), was the first of three known minor conflicts during the Eighty Years'' War between the Dutch Republic and Spain held in Playa Honda (present-day Botolan) in the Philippines. All the battles were won by the Spanish.', 1617, 4, 14, 1617, 4, 15, 'day', '14 April 1617 – 15 April 1617', 37, 'https://en.wikipedia.org/wiki/Battle_of_Playa_Honda'),
  ('Q2265603', 'Battles of La Naval de Manila', 'The Battles of La Naval de Manila or Battle of Manila Bay (Spanish: Batallas de las marinas de Manila) were a series of five naval battles fought in the waters of the Spanish East Indies in the year 1646, in which the forces of the Spanish Empire repelled various attempts by forces of the Dutch Republic to invade Manila, during the Eighty Years'' War. The Spanish forces, which included many native volunteers, consisted of two, and later, three Manila galleons, a galley and four brigantines.', 1646, 3, 15, 1646, 10, 4, 'day', '15 March 1646 – 4 October 1646', 37, 'https://en.wikipedia.org/wiki/Battles_of_La_Naval_de_Manila'),
  ('Q2890933', 'Battle of Puerto de Cavite', 'The naval Battle of Puerto de Cavite (Spanish: La Batalla del Puerto de Cavite; Filipino: Labanan sa Puerto ng Cavite) took place on 10 June 1647 during the Eighty Years'' War between a Spanish fleet and a Dutch fleet in Puerto de Cavite, an important Spanish port in Manila Bay, Philippines in which the Dutch were defeated.', 1647, 6, 10, NULL, NULL, NULL, 'day', '10 June 1647', 39, 'https://en.wikipedia.org/wiki/Battle_of_Puerto_de_Cavite'),
  ('Q2617813', 'Battle of Manila', 'The Battle of Manila was fought during the Seven Years'' War, from 24 September 1762 to 6 October 1762, between the Kingdom of Great Britain and the Kingdom of Spain in and around Manila, the capital of the Philippines, a Spanish colony at that time. The British won, leading to an eighteen-month occupation of Manila.', 1762, 9, 24, 1762, 10, 6, 'day', '24 September 1762 – 6 October 1762', 48, 'https://en.wikipedia.org/wiki/Battle_of_Manila_(1762)'),
  ('Q422082', 'Philippine Revolution', 'The Philippine Revolution was a war of independence waged by the revolutionary organization Katipunan against the Spanish Empire from 1896 to 1898. It was the culmination of the 333-year colonial rule of Spain in the archipelago.', 1896, NULL, NULL, 1898, NULL, NULL, 'year', '1896–1898', 75, 'https://en.wikipedia.org/wiki/Philippine_Revolution'),
  ('Q69772', 'Philippine Declaration of Independence', 'The Philippine Declaration of Independence (Tagalog: Pagpapahayag ng Kasarinlan ng Pilipinas; Spanish: Declaración de Independencia de Filipinas) was proclaimed by Filipino revolutionary forces general Emilio Aguinaldo on June 12, 1898, in Cavite el Viejo (present-day Kawit, Cavite), Philippines. It asserted the sovereignty and independence of the Philippine islands from the 300 years of colonial rule by Spain.', 1898, 6, 12, NULL, NULL, NULL, 'day', '12 June 1898', 58, 'https://en.wikipedia.org/wiki/Philippine_Declaration_of_Independence'),
  ('Q303176', 'Battle of Manila', 'The Battle of Manila (Filipino: Labanan sa Maynila; Spanish: Batalla de Manila), sometimes called the Mock Battle of Manila, was a land engagement which took place in Manila on August 13, 1898, at the end of the Spanish–American War, three months after the decisive victory by Commodore Dewey''s Asiatic Squadron at the Battle of Manila Bay. The belligerents were Spanish forces led by Governor-General of the Philippines Fermín Jáudenes, and American forces led by United States Army Major General Wesley Merritt and United States Navy Commodore George Dewey.', 1898, 8, 13, NULL, NULL, NULL, 'day', '13 August 1898', 41, 'https://en.wikipedia.org/wiki/Battle_of_Manila_(1898)'),
  ('Q528550', 'Battle of Manila Bay', 'The Battle of Manila Bay, also known as the Battle of Cavite, took place on May 1, 1898, during the Spanish–American War. The United States Navy''s Asiatic Squadron under Commodore George Dewey engaged and destroyed the Spanish Navy''s Pacific Squadron under Counter-admiral Patricio Montojo y Pasarón.', 1898, 5, 1, NULL, NULL, NULL, 'day', '1 May 1898', 61, 'https://en.wikipedia.org/wiki/Battle_of_Manila_Bay'),
  ('Q778699', 'Siege of Baler', 'The Siege of Baler (Filipino: Pagkubkob sa Baler; Spanish: Sitio de Baler) was a battle of the Philippine Revolution. Filipino revolutionaries laid siege to a fortified church defended by Spanish troops in the town of Baler in the district of El Principe, Nueva Ecija (present-day part of Aurora), for 337 days, from 1 July 1898 until 2 June 1899.', 1898, 7, 1, 1899, 6, 2, 'day', '1 July 1898 – 2 June 1899', 52, 'https://en.wikipedia.org/wiki/Siege_of_Baler'),
  ('Q746860', 'Battle of Manila', 'The Battle of Manila (Filipino: Labanan sa Maynila; Spanish: Batalla de Manila), the first and largest battle of the Philippine–American War, was fought on February 4–5, 1899, between 19,000 American and 15,000 Filipino soldiers. Armed conflict erupted when American troops, tasked with preventing the Filipino encampment from moving closer, fired on a nearby group.', 1899, NULL, NULL, 1899, 2, 5, 'year', '1899', 48, 'https://en.wikipedia.org/wiki/Battle_of_Manila_(1899)'),
  ('Q202192', 'Balangiga Massacre', 'The Balangiga massacre was an incident in which the residents of the town of Balangiga on the Philippines island of Samar conducted a surprise attack on an occupying unit of the US 9th Infantry, killing 54. It is also known as the Battle of Balangiga, Balangiga encounter, Balangiga incident, or Balangiga conflict.', 1901, 9, 28, NULL, NULL, NULL, 'day', '28 September 1901', 39, 'https://en.wikipedia.org/wiki/Battle_of_Balangiga'),
  ('Q4118051', 'First Battle of Bud Dajo', 'The First Battle of Bud Dajo, also known as the Moro Crater Massacre, was a counterinsurgency action conducted by the United States Army and Marine Corps against the Moro people in March 1906, during the Moro Rebellion in the southwestern Philippines. During the engagement, 750 men and officers, under the command of Colonel Joseph Wilson Duncan, assaulted the volcanic crater of Bud Dajo (Tausug: Būd Dahu), which was populated by 800 to 1,000 Tausūg villagers.', 1906, 3, 5, 1906, 3, 8, 'day', '5 March 1906 – 8 March 1906', 41, 'https://en.wikipedia.org/wiki/First_Battle_of_Bud_Dajo'),
  ('Q4870584', 'Battle of Bud Bagsak', 'The Battle of Bud Bagsak took place during the Moro Rebellion phase of the Philippine–American War fought between June 11 and 15, 1913. The defending Moro fighters were fortified at the top of Mount Bagsak on the island of Jolo, Sulu.', 1913, NULL, NULL, 1913, 6, 15, 'year', '1913', 43, 'https://en.wikipedia.org/wiki/Battle_of_Bud_Bagsak'),
  ('Q696462', 'Philippines Campaign', 'The Philippines campaign, also known as the Battle of the Philippines (Filipino: Labanan sa Pilipinas) or the Fall of the Philippines, was the invasion of the Philippines by the Empire of Japan during the Pacific War and World War II. The operation to capture the islands, which was defended by the U.S. and Philippine Armies, was intended to prevent interference with Japan''s expansion in Southeast Asia. On 8 December 1941, several hours after the attack on Pearl Harbor, Japanese planes began bombing U.S. forces in the Philippines, including aircraft at Clark Field near the capital of Manila…', 1941, 12, 8, 1942, 5, 8, 'day', '8 December 1941 – 8 May 1942', 68, 'https://en.wikipedia.org/wiki/Philippines_campaign_(1941%E2%80%931942)'),
  ('Q703482', 'Battle of Bataan', 'The Battle of Bataan (Filipino: Labanan sa Bataan; 7 January – 9 April 1942) was fought by the United States and the Philippine Commonwealth against the Empire of Japan during World War II. The battle represented the most intense phase of the Japanese invasion of the Philippines during World War II. In January 1942, forces of the Imperial Japanese Army and Navy invaded Luzon along with several islands in the Philippine Archipelago after the bombing of the American naval base at Pearl Harbor. The commander in chief of the U.S. and Filipino forces in the islands, General Douglas MacArthur,…', 1942, 1, 7, 1942, 4, 9, 'day', '7 January 1942 – 9 April 1942', 57, 'https://en.wikipedia.org/wiki/Battle_of_Bataan'),
  ('Q713006', 'Battle of Corregidor', 'The Battle of Corregidor (Filipino: Labanan sa Corregidor; Japanese: コレヒドールの戦い), fought on 5–6 May 1942, was the culmination of the Japanese campaign for the conquest of the Commonwealth of the Philippines during World War II. The fall of Bataan on 9 April 1942 ended all organized opposition by the United States Army Forces in the Far East to the invading Japanese forces on Luzon, in the northern Philippines. The island bastion of Corregidor, with its network of tunnels and formidable array of defensive armaments, along with the fortifications across the entrance to Manila Bay, was the…', 1942, NULL, NULL, 1942, 5, 6, 'year', '1942', 57, 'https://en.wikipedia.org/wiki/Battle_of_Corregidor'),
  ('Q3175954', 'Japanese occupation of the Philippines', 'The Japanese Empire occupied the Commonwealth of the Philippines between 1942 and 1945 during World War II. Japan invaded the Philippines on December 8, 1941, ten hours after the attack on Pearl Harbor. As at Pearl Harbor, American aircraft were severely damaged in the initial Japanese attack.', 1942, 5, 8, 1945, 7, 5, 'day', '8 May 1942 – 5 July 1945', 55, 'https://en.wikipedia.org/wiki/Japanese_occupation_of_the_Philippines'),
  ('Q711223', 'Battle of Mindoro', 'The Battle of Mindoro (Filipino: Labanan sa Mindoro) took place during World War II between the forces of the United States and Japan, in Mindoro Island in the central Philippines, from 13 to 16 December 1944, during the Philippines campaign. Troops of the United States Army, supported by the United States Navy and US Army Air Forces (USAAF), made an amphibious landing on Mindoro and defeated Imperial Japanese Army (IJA) forces there.', 1944, NULL, NULL, 1944, 12, 16, 'year', '1944', 52, 'https://en.wikipedia.org/wiki/Battle_of_Mindoro'),
  ('Q717004', 'Battle of Leyte', 'The Battle of Leyte (Filipino: Labanan sa Leyte; Waray: Gubat ha Leyte; Japanese: レイテの戦い) in the Pacific campaign of World War II was the amphibious invasion of the island of Leyte in the Philippines by American forces and Filipino guerrillas under the overall command of General Douglas MacArthur. The combined forces fought against the Imperial Japanese Army in the Philippines led by General Tomoyuki Yamashita.', 1944, 10, 17, 1944, 12, 26, 'day', '17 October 1944 – 26 December 1944', 62, 'https://en.wikipedia.org/wiki/Battle_of_Leyte'),
  ('Q718805', 'Battle of Ormoc Bay', 'The Battle of Ormoc Bay was a series of air-sea battles between Imperial Japan and the United States in the Camotes Sea in the Philippines from 9 November to 21 December 1944, at Ormoc, part of the Battle of Leyte in the Pacific campaign of World War II. The battles resulted from Japanese operations to reinforce and resupply their forces on Leyte and U.S. attempts to interdict them.', 1944, 11, 11, 1944, 12, 21, 'day', '11 November 1944 – 21 December 1944', 52, 'https://en.wikipedia.org/wiki/Battle_of_Ormoc_Bay'),
  ('Q371573', 'Philippines campaign of 1944–1945', 'The Philippines campaign, codenamed Operation Musketeer I, II, and III, was the American, Filipino, Australian, and Mexican campaign to defeat and expel the Imperial Japanese forces occupying the Philippines during World War II. The Imperial Japanese Army overran all of the Philippines during the first half of 1942. Two years later, the liberation of the Philippines from Japan commenced with amphibious landings on the eastern Philippine island of Leyte on 20 October 1944.', 1945, 9, 2, 1945, 8, 15, 'day', '2 September 1945 – 15 August 1945', 69, 'https://en.wikipedia.org/wiki/Philippines_campaign_(1944%E2%80%931945)'),
  ('Q696931', 'Battle of Manila', 'The Battle of Manila (3 February – 3 March 1945) was a major battle during the Philippine campaign of 1944–45, during the Second World War. It was fought by forces from both the United States and the Philippines against Imperial Japanese troops in Manila, the capital city of the Philippines.', 1945, NULL, NULL, 1945, 3, 3, 'year', '1945', 65, 'https://en.wikipedia.org/wiki/Battle_of_Manila_(1945)'),
  ('Q699787', 'Manila massacre', 'The Manila massacre (Filipino: Pagpatay sa Maynila or Masaker sa Maynila), also called the Rape of Manila (Paggahasa ng Maynila), involved atrocities committed against Filipino civilians in the City of Manila, the capital of the Philippines, by Japanese troops during the Battle of Manila (3 February 1945 – 3 March 1945) which occurred during World War II. At least 100,000 civilians were killed in total during the battle from all causes, including the massacre by Japanese troops. The Manila massacre was one of several major war crimes committed by the Imperial Japanese Navy.', 1945, NULL, NULL, NULL, NULL, NULL, 'year', '1945', 60, 'https://en.wikipedia.org/wiki/Manila_massacre'),
  ('Q702449', 'Battle of Bataan', 'The Battle for the Recapture of Bataan (Filipino: Labanan para sa Bataan) from 31 January to 21 February 1945, by US forces and Allied Filipino guerrillas from the Japanese, part of the campaign for the liberation of the Philippines, was waged to secure the western shore of Manila Bay to enable the use of its harbor and open new supply lines for American troops engaged in the crucial battle for the liberation of Manila. The Bataan peninsula''s recapture also avenged the surrender of the US Army Luzon Force to invading Japanese forces on 9 April 1942.', 1945, 1, 31, 1945, 2, 21, 'day', '31 January 1945 – 21 February 1945', 43, 'https://en.wikipedia.org/wiki/Battle_of_Bataan_(1945)'),
  ('Q702568', 'Battle of Corregidor', 'The Battle of Corregidor (Filipino: Labanan para sa Corregidor), which occurred from 16 to 26 February 1945, pitted American forces against the defending Japanese garrison on the island fortress. The Japanese had captured the bastion from the United States Army Forces in the Far East during their 1942 invasion.', 1945, 2, 26, 1945, 2, 26, 'day', '26 February 1945', 45, 'https://en.wikipedia.org/wiki/Battle_of_Corregidor_(1945)'),
  ('Q703962', 'Battle of Luzon', 'The Battle of Luzon (Tagalog: Labanan sa Luzon; Japanese: ルソン島の戦い; Spanish: Batalla de Luzón) was a land battle of the Pacific Theater of Operations of World War II by the Allied forces of the U.S., the Philippines, Mexico, and other allies against forces of the Empire of Japan. The battle resulted in a U.S., Filipino and Mexican victory.', 1945, 1, 9, 1945, 8, 15, 'day', '9 January 1945 – 15 August 1945', 59, 'https://en.wikipedia.org/wiki/Battle_of_Luzon'),
  ('Q710912', 'Battle of Mindanao', 'The Battle of Mindanao (Filipino: Labanan sa Mindanaw; Cebuano: Panagsangka sa Mindanaw; Japanese: ミンダナオの戦い) was fought by the Americans and allied Filipino guerrillas against the Japanese forces on the island of Mindanao in the Philippines as part of Operation VICTOR V. It was part of the campaign to liberate the Philippines during World War II. The battle was waged to complete the recapture of the southernmost portions of the archipelago from the Imperial Japanese Army.', 1945, 3, 10, 1945, 8, 15, 'day', '10 March 1945 – 15 August 1945', 52, 'https://en.wikipedia.org/wiki/Battle_of_Mindanao'),
  ('Q710939', 'Battle of the Visayas', 'The Battle of Visayas (Filipino: Labanan sa Visayas; Visayan languages: Gubat sa Kabisay-an) was fought by U.S. forces and Filipino guerrillas against the Japanese from 18 March – 15 August 1945, in a series of actions officially designated as Operations Victor I and II, and part of the campaign for the liberation of the Philippines during World War II. The battle was waged to complete the recapture of the central portions south of the archipelago and secure them from remaining Japanese forces.', 1945, 3, 18, 1945, 7, 30, 'day', '18 March 1945 – 30 July 1945', 45, 'https://en.wikipedia.org/wiki/Battle_of_Visayas'),
  ('Q13403526', 'Invasion of Palawan', 'The Invasion of Palawan (Filipino: Paglusob sa Palawan) consisted of a series of actions officially designated Operation Victor I and Operation Victor II, fought by U.S. forces against the Japanese military from 28 February to 22 April 1945 as a part of the campaign for the liberation of the Philippines during World War II. The aim of the invasion was the recapture of the southern islands of the Philippine archipelago and liberating them from Japanese occupation.', 1945, 2, 28, 1945, 4, 22, 'day', '28 February 1945 – 22 April 1945', 37, 'https://en.wikipedia.org/wiki/Invasion_of_Palawan'),
  ('Q7837141', 'Treaty of Manila', 'The Treaty of Manila of 1946, formally the Treaty of General Relations and Protocol, is a treaty of general relations signed on July 4, 1946, in Manila, the capital of the Philippines. It relinquished U.S. sovereignty over the Philippines and recognized the independence of the Republic of the Philippines.', 1946, NULL, NULL, NULL, NULL, NULL, 'year', '1946', 52, 'https://en.wikipedia.org/wiki/Treaty_of_Manila_(1946)'),
  ('Q5463546', 'Flying Tiger Line Flight 739', 'Flying Tiger Line Flight 739 was a Lockheed L-1049 Super Constellation propliner that disappeared on March 16, 1962, over the western Pacific Ocean. The aircraft, which had been chartered by the United States Army, was transporting ninety-six military passengers from Travis Air Force Base in California to Tan Son Nhat International Airport in Saigon, South Vietnam.', 1962, 3, 16, NULL, NULL, NULL, 'day', '16 March 1962', 51, 'https://en.wikipedia.org/wiki/Flying_Tiger_Line_Flight_739'),
  ('Q16146546', 'Civil conflict in the Philippines', 'The civil conflict in the Philippines is a series of insurgencies launched by Communist rebels, Moro rebels, and Islamists against Government forces that began in 1969 during the presidency of Ferdinand Marcos.', 1969, 3, 29, NULL, NULL, NULL, 'day', '29 March 1969', 47, 'https://en.wikipedia.org/wiki/Civil_conflict_in_the_Philippines'),
  ('Q4577217', '1976 Moro Gulf Erdbeben', 'The 1976 Moro Gulf earthquake and tsunami occurred on August 17, 1976, at 00:11 local time near the islands of Mindanao and Sulu, in the Philippines. It measured 8.0 on the moment magnitude scale occurring at a depth of 20 km (12 mi).', 1976, 8, 16, NULL, NULL, NULL, 'day', '16 August 1976', 45, 'https://en.wikipedia.org/wiki/1976_Moro_Gulf_earthquake'),
  ('Q4808502', 'assassination of Benigno Aquino, Jr.', 'On August 21, 1983, Benigno "Ninoy" Aquino Jr., a former Philippine senator, was assassinated with a gunshot to the head on the apron of what was then Manila International Airport. Aquino, a longtime opponent of President Ferdinand Marcos Sr., had just returned from three years of self-imposed exile in the United States, and was being taken to a vehicle which would return him to prison.', 1983, 8, 21, NULL, NULL, NULL, 'day', '21 August 1983', 41, 'https://en.wikipedia.org/wiki/Assassination_of_Ninoy_Aquino'),
  ('Q2885880', '1990 Luzon earthquake', 'The 1990 Luzon earthquake occurred on July 16 at 4:26 p.m. (PHDT) on the densely populated island of Luzon in the Philippines.', 1990, 7, 16, NULL, NULL, NULL, 'day', '16 July 1990', 50, 'https://en.wikipedia.org/wiki/1990_Luzon_earthquake'),
  ('Q4016236', 'Cebu Pacific Flight 387', 'Cebu Pacific Flight 387 was a domestic flight from Ninoy Aquino International Airport in Metro Manila to Lumbia Airfield (formerly Lumbia Airport) in Cagayan de Oro. On February 2, 1998, the 30-year-old McDonnell Douglas DC-9-32 crashed on the slopes of Mount Sumagaya in Claveria.', 1998, 2, 2, NULL, NULL, NULL, 'day', '2 February 1998', 51, 'https://en.wikipedia.org/wiki/Cebu_Pacific_Flight_387'),
  ('Q4261034', 'Philippine Airlines Flight 137', 'Philippine Airlines Flight 137 was a scheduled passenger flight from Ninoy Aquino International Airport in Metro Manila to Bacolod City Domestic Airport in Bacolod. The Airbus A320 overran the runway on landing which resulted in the deaths of three people on the ground whereas none out of the 124 passengers and 6 crew were killed.', 1998, 3, 22, NULL, NULL, NULL, 'day', '22 March 1998', 45, 'https://en.wikipedia.org/wiki/Philippine_Airlines_Flight_137'),
  ('Q1980316', 'EDSA Revolution of 2001', 'The Second EDSA Revolution (Filipino: Ikalawang Rebolusyon sa EDSA), also known as the Second People Power Revolution, EDSA 2001, or EDSA II (pronounced EDSA Two or EDSA Dos, the Spanish and Filipino slang word for "two"), was a political protest from January 17–20, 2001 which peacefully overthrew the government of Joseph Estrada, the thirteenth president of the Philippines. Following allegations of corruption against Estrada and his subsequent investigation by Congress, impeachment proceedings against the president were opened on January 16.', 2001, 1, 17, 2001, 1, 20, 'day', '17 January 2001 – 20 January 2001', 47, 'https://en.wikipedia.org/wiki/Second_EDSA_Revolution'),
  ('Q1518023', 'Maguindanao massacre', 'The Maguindanao massacre (also known as the Ampatuan massacre, named after the town where mass graves of victims were found) occurred on the morning of November 23, 2009, in the town of Ampatuan in Maguindanao, Philippines (now located in Maguindanao del Sur). The 58 victims were on their way to file a certificate of candidacy for Esmael Mangudadatu, vice-mayor of Buluan, when they were kidnapped and later killed.', 2009, 11, 23, NULL, NULL, NULL, 'day', '23 November 2009', 56, 'https://en.wikipedia.org/wiki/Maguindanao_massacre'),
  ('Q679519', '2012 Visayas earthquake', 'The 2012 Negros earthquake occurred on February 6, 2012 at 11:49 AM PST, with a body wave magnitude of 6.7 and a maximum intensity of VII (Destructive) off the coast of Negros Oriental, Philippines. The epicenter of the thrust fault earthquake was approximately 72 kilometres (45 mi) north of Negros Oriental''s provincial capital, Dumaguete.', 2012, 2, 6, NULL, NULL, NULL, 'day', '6 February 2012', 48, 'https://en.wikipedia.org/wiki/2012_Negros_earthquake'),
  ('Q14916975', 'Zamboanga City crisis', 'The Zamboanga siege (Filipino: Pagkubkob sa Zamboanga; Chavacano: Asedio na Zamboanga; Tausug: Pagkubkub ha Sambuwangan) was an armed conflict in Zamboanga City, Philippines, between government forces of the Philippines and a rogue faction of the Moro National Liberation Front (MNLF) that began on September 9, 2013, and ended twenty days later on September 28. The conflict began when rogue MNLF rebels, under the command of Ustadz Habier Malik, attempted to occupy several coastal communities in Zamboanga City in protest of the Philippine government''s failure to implement the 1996 Final Peace…', 2013, 9, NULL, NULL, NULL, NULL, 'month', 'September 2013', 37, 'https://en.wikipedia.org/wiki/Zamboanga_siege'),
  ('Q15071846', '2013 Philippines earthquake', 'The 2013 Bohol earthquake occurred on October 15 at 8:12:31 PST in Bohol, an island province located in Central Visayas, Philippines. The magnitude of the earthquake was recorded at Mw 7.2, its epicenter in the vicinity of 6 kilometres (3.7 mi) S 24° W of Sagbayan, and its depth of focus at 12 kilometres (7.5 mi).', 2013, 10, 15, NULL, NULL, NULL, 'day', '15 October 2013', 56, 'https://en.wikipedia.org/wiki/2013_Bohol_earthquake'),
  ('Q18916791', '2015 Mamasapano clash', 'The Mamasapano clash was a shootout that took place during a police operation by the Special Action Force (SAF) of the Philippine National Police (PNP) on January 25, 2015, in Tukanalipao, Mamasapano, then-undivided Maguindanao (which is now Maguindanao del Sur). The operation, codenamed Oplan Exodus, was intended to capture or kill wanted Malaysian terrorist and bomb-maker Zulkifli Abdhir and other Malaysian terrorists or high-ranking members of the Moro Islamic Liberation Front (MILF).', 2015, 1, 25, NULL, NULL, NULL, 'day', '25 January 2015', 41, 'https://en.wikipedia.org/wiki/Mamasapano_clash'),
  ('Q30041564', 'Siege of Marawi', 'The siege of Marawi (Filipino: Pagkubkob sa Marawi), also known as the Marawi crisis (Krisis sa Marawi) and the Battle of Marawi (Labanan sa Marawi), was a five-month-long armed conflict in Marawi, Philippines, that started on May 23, 2017, between Philippine government security forces against militants affiliated with the Islamic State (IS), including the Maute and Abu Sayyaf Salafi jihadist groups. The battle also became the longest urban battle in the modern history of the Philippines.', 2017, 10, 23, NULL, NULL, NULL, 'day', '23 October 2017', 62, 'https://en.wikipedia.org/wiki/Siege_of_Marawi'),
  ('Q61042203', '2019 Jolo Cathedral bombing', 'In the morning of January 27, 2019, two bombs exploded at the Roman Catholic Cathedral of Our Lady of Mount Carmel in Jolo, Sulu, Philippines. Twenty people were killed and 102 others injured.', 2019, 1, 27, NULL, NULL, NULL, 'day', '27 January 2019', 58, 'https://en.wikipedia.org/wiki/2019_Jolo_Cathedral_bombings'),
  ('Q63254483', '2019 Luzon earthquake', 'On April 22, 2019, at 5:11:09 p.m. (PST), an earthquake with a magnitude of 6.1Mw struck the island of Luzon in the Philippines, leaving at least 18 dead, three missing and injuring at least 256 others.', 2019, 4, 22, NULL, NULL, NULL, 'day', '22 April 2019', 48, 'https://en.wikipedia.org/wiki/2019_Luzon_earthquake'),
  ('Q65967109', '2019 Batanes earthquake', 'The 2019 Batanes earthquake was a magnitude 6.0 earthquake which struck Batanes, Philippines on July 27, 2019. It was preceded by a 5.4 magnitude foreshock.', 2019, 7, 27, NULL, NULL, NULL, 'day', '27 July 2019', 37, 'https://en.wikipedia.org/wiki/2019_Batanes_earthquake'),
  ('Q71241011', '2019 Cotabato earthquakes', 'The 2019 Cotabato earthquakes were an earthquake swarm which struck the province of Cotabato on the island of Mindanao in the Philippines in October 2019. Three of these earthquakes were above 6.0 on the moment magnitude scale with a Mercalli intensity of VIII. More than 40 people have been reported dead or missing and nearly 800 were injured as a result of these events.', 2019, 10, NULL, NULL, NULL, NULL, 'month', 'October 2019', 48, 'https://en.wikipedia.org/wiki/2019_Cotabato_earthquakes'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q81914341', '2020–2022 Taal Volcano eruptions', 'Taal Volcano in Batangas, Philippines began to erupt on January 12, 2020, when a phreatomagmatic eruption from its main crater spewed ashes over Calabarzon, Metro Manila, and some parts of Central Luzon and Ilocos Region, resulting in the suspension of school classes, work schedules, and flights in the area, as well as temporarily drying up Taal Main Crater Lake and destroying Vulcan Point, an Island surrounded by the lake. The Philippine Institute of Volcanology and Seismology (PHIVOLCS) subsequently issued an Alert Level 4, indicating "that a hazardous explosive eruption is possible…', 2020, 1, 12, NULL, NULL, NULL, 'day', '12 January 2020', 51, 'https://en.wikipedia.org/wiki/2020%E2%80%932022_Taal_Volcano_eruptions'),
  ('Q98605615', '2020 Jolo bombings', 'The 2020 Jolo bombings occurred on August 24, 2020, when insurgents alleged to be jihadists from the Abu Sayyaf group detonated two bombs in Jolo, Sulu, Philippines, killing 14 people and wounding 75 others. The first occurred as Philippine Army personnel were assisting in carrying out COVID-19 humanitarian efforts.', 2020, 8, 24, NULL, NULL, NULL, 'day', '24 August 2020', 52, 'https://en.wikipedia.org/wiki/2020_Jolo_bombings'),
  ('Q113297332', '2022 Luzon earthquake', 'On July 27, 2022, at 8:43:24 a.m. (PHT), an earthquake struck the island of Luzon in the Philippines.', 2022, 7, 27, NULL, NULL, NULL, 'day', '27 July 2022', 50, 'https://en.wikipedia.org/wiki/2022_Luzon_earthquake'),
  ('Q114836063', 'Korean Air Flight 631', 'Korean Air Flight 631 was a scheduled international passenger flight operating from Incheon International Airport near Seoul, South Korea to Mactan–Cebu International Airport in Metro Cebu, Philippines. On 23 October 2022, the Airbus A330 operating this flight overran the runway while landing in Cebu due to a failure with the hydraulics system.', 2022, 10, 23, NULL, NULL, NULL, 'day', '23 October 2022', 47, 'https://en.wikipedia.org/wiki/Korean_Air_Flight_631'),
  ('Q123474732', 'November 2023 Mindanao earthquake', 'At 16:14 PST (08:14 UTC) on November 17, 2023, the province of Sarangani on the island of Mindanao in the Philippines was struck by an earthquake measuring Mww 6.7 or Mw 6.8. It had a maximum perceived intensity of VIII (Severe) on the Modified Mercalli Intensity Scale.', 2023, 11, 17, NULL, NULL, NULL, 'day', '17 November 2023', 45, 'https://en.wikipedia.org/wiki/November_2023_Mindanao_earthquake'),
  ('Q123614250', 'December 2023 Mindanao earthquake', 'On December 2, 2023, at 22:37 PST (14:37 UTC), a moment magnitude (Mww) 7.6 earthquake occurred off the island of Mindanao in the Philippines. The shallow subduction earthquake killed at least three people and left 79 injured.', 2023, 12, 2, NULL, NULL, NULL, 'day', '2 December 2023', 45, 'https://en.wikipedia.org/wiki/December_2023_Mindanao_earthquake'),
  ('Q136409338', '2025 Cebu earthquake', 'On September 30, 2025, at 21:59:43 PHT (13:59:43 UTC), an earthquake with a magnitude of 6.9 on the moment magnitude scale (Mw) struck the Visayas archipelago in the Philippines. It was the strongest earthquake ever recorded in northern Cebu and the deadliest in the country since 2013, with its epicenter located off the coast of Cebu Province in the Central Visayas region.', 2025, 9, 30, NULL, NULL, NULL, 'day', '30 September 2025', 56, 'https://en.wikipedia.org/wiki/2025_Cebu_earthquake'),
  ('Q140119396', '2026 Mindanao earthquake', 'On June 8, 2026, at 07:37:40 PhST (23:37:40 UTC on June 7), a Mw 7.8 earthquake struck offshore southern Mindanao in the Philippines. The United States Geological Survey located the epicenter approximately 25 km (16 mi) southwest of Kablalan at a depth of about 57 km (35 mi), while the Philippine Institute of Volcanology and Seismology located it 32 km (20 mi) south of Maasim, Sarangani, at a depth of 33 km (21 mi).', 2026, 6, 8, NULL, NULL, NULL, 'day', '8 June 2026', 65, 'https://en.wikipedia.org/wiki/2026_Mindanao_earthquake'),
  ('Q141416648', 'MV June Aster ship fire', 'On the evening of September 9, 2026, the Philippine passenger-cargo vessel MV June Aster caught fire in the waters off Coron, Palawan. The ferry was carrying 128 passengers and 17 crew members when the fire broke out.', 2026, 9, 9, NULL, NULL, NULL, 'day', '9 September 2026', 43, 'https://en.wikipedia.org/wiki/MV_June_Aster_ship_fire');
